import json,re,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];RAW=(R/'raw/Dhika.txt').read_bytes();L=RAW.decode().split('\n')
E=json.loads((R/'data/female_action_review/manifest.json').read_text())['episodes'];SHA=hashlib.sha256(RAW).hexdigest()
assert SHA=='7e7ee52792f41f18f0c0b1ce4fb3f62ba932eb333dbc72493e879b05dfd12dbb'
def ref(n):
 e=next(e for e in E if e['global_line_start']<=n<=e['global_line_end'])
 return dict(global_line=n,episode_id=e['episode_id'],episode_line=n-e['global_line_start']+1,text=L[n-1])
def target(owner,part,mode,layer='not_stated',note=None):return dict(owner=owner,body_part=part,mode=mode,contact_layer=layer,qualification=note,context_evidence_global_lines=[])
def new(title,owners,names):return dict(title=title,owners=owners,names=names,scenes=[],beats=[],actions=[],styles=[],uncertainties=[])
def scene(p,mid,title,sections,time):p['scenes'].append(dict(meeting_id=mid,title=title,sections=sections,time_anchor=time))
def beat(p,a,b,title,reading,kind='conversation',mid=None,fields=(),recalls=()):p['beats'].append(dict(start=a,end=b,title=title,reading=reading,kind=kind,meeting_id=mid,state_fields=list(fields),recalls_meeting_ids=list(recalls)))
def act(p,ns,title,who,targets=(),frame='actual',context=()):
 if isinstance(ns,int):ns=[ns]
 p['actions'].append(dict(lines=ns,action=title,initiated_by=who,targets=list(targets),temporal_frame=frame,context=list(context)))
def style(p,a,b,title,text):p['styles'].append(dict(title=title,lines=list(range(a,b+1)),observation=text))
def issue(p,ns,text):p['uncertainties'].append(dict(lines=ns,issue=text))
